import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine } from '../src/invoices.js';

test('createInvoice creates a draft invoice with valid data', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].sku, 'DES-HOUR');
  assert.equal(result.value.lines[0].name, 'Design work (hour)');
  assert.equal(result.value.lines[0].qty, 2);
  assert.ok(Number.isInteger(result.value.lines[0].unitPrice));
  assert.ok([0, 9, 21].includes(result.value.lines[0].vatRate));
});

test('createInvoice reports unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice reports invalid date format', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '10/07/2026',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports invalid date value', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-02-30',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports missing date', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice reports empty lines array', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [],
  });
  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports non-array lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: null,
  });
  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports non-integer quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2.5 }],
  });
  assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports zero quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 0 }],
  });
  assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports negative quantity', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: -5 }],
  });
  assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice reports unknown SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'NOPE', qty: 1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice validates qty before SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'NOPE', qty: 2.5 },
    ],
  });
  assert.equal(result.error, 'QTY_INVALID');
});

test('createInvoice does not mutate the input', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  };
  const inputCopy = JSON.stringify(input);
  createInvoice(input);
  assert.equal(JSON.stringify(input), inputCopy);
});

test('createInvoice returns independent copies of lines', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  result1.value.lines[0].qty = 999;
  const result2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  assert.equal(result2.value.lines[0].qty, 2);
});

test('createInvoice copies product info from catalogue', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.ok(result.value.lines[0].name);
  assert.ok(result.value.lines[0].unitPrice > 0);
  assert.ok(result.value.lines[0].vatRate >= 0);
});

test('lineTotal calculates qty times unitPrice', () => {
  const line = { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 };
  assert.equal(lineTotal(line), 42500);
});

test('lineTotal works with qty of 1', () => {
  const line = { qty: 1, unitPrice: 1299 };
  assert.equal(lineTotal(line), 1299);
});

test('lineTotal works with large quantities', () => {
  const line = { qty: 1000, unitPrice: 100 };
  assert.equal(lineTotal(line), 100000);
});

test('invoiceTotals returns object with subtotal and total', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 2, unitPrice: 8500, vatRate: 21 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 3, unitPrice: 9500, vatRate: 21 },
    ],
  };
  const result = invoiceTotals(invoice);
  assert.ok('subtotal' in result);
  assert.ok('total' in result);
});

test('invoiceTotals.subtotal is the sum of line totals', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 8500 },
      { qty: 3, unitPrice: 9500 },
      { qty: 1, unitPrice: 1299 },
    ],
  };
  const result = invoiceTotals(invoice);
  assert.equal(result.subtotal, 2 * 8500 + 3 * 9500 + 1 * 1299);
  assert.equal(result.subtotal, 17000 + 28500 + 1299);
  assert.equal(result.subtotal, 46799);
});

test('invoiceTotals.total equals subtotal (before VAT)', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 8500 },
      { qty: 3, unitPrice: 9500 },
    ],
  };
  const result = invoiceTotals(invoice);
  assert.equal(result.total, result.subtotal);
});

test('invoiceTotals works with a single line', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 6000 }],
  };
  const result = invoiceTotals(invoice);
  assert.equal(result.subtotal, 30000);
  assert.equal(result.total, 30000);
});

test('invoiceTotals works with mixed VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 8500, vatRate: 21 },
      { qty: 1, unitPrice: 2490, vatRate: 9 },
      { qty: 3, unitPrice: 60000, vatRate: 0 },
    ],
  };
  const result = invoiceTotals(invoice);
  assert.equal(result.subtotal, 2 * 8500 + 1 * 2490 + 3 * 60000);
  assert.equal(result.subtotal, 17000 + 2490 + 180000);
  assert.equal(result.subtotal, 199490);
});

test('invoiceTotals does not mutate the input', () => {
  const invoice = {
    lines: [{ qty: 2, unitPrice: 8500 }],
  };
  const invoiceCopy = JSON.stringify(invoice);
  invoiceTotals(invoice);
  assert.equal(JSON.stringify(invoice), invoiceCopy);
});

test('addLine adds a new line to a draft invoice', () => {
