});

test('lineTotal calculates qty times unitPrice', () => {
  const line = { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 5, unitPrice: 8500, vatRate: 21 };
  assert.equal(lineTotal(line), 42500);
});

test('lineTotal works with qty of 1', () => {
  const line = { qty: 1, unitPrice: 1299 };
  assert.equal(lineTotal(line), 1299);
});

test('lineTotal works with large quantities', () => {
  const line = { qty: 1000, unitPrice: 100 };
  assert.equal(lineTotal(line), 100000);
});

test('invoiceTotals returns object with subtotal and total', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 2, unitPrice: 8500, vatRate: 21 },
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 3, unitPrice: 9500, vatRate: 21 },
    ],
  };
  const result = invoiceTotals(invoice);
  assert.ok('subtotal' in result);
  assert.ok('total' in result);
});

test('invoiceTotals.subtotal is the sum of line totals', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 8500 },
      { qty: 3, unitPrice: 9500 },
      { qty: 1, unitPrice: 1299 },
    ],
  };
  const result = invoiceTotals(invoice);
  assert.equal(result.subtotal, 2 * 8500 + 3 * 9500 + 1 * 1299);
  assert.equal(result.subtotal, 17000 + 28500 + 1299);
  assert.equal(result.subtotal, 46799);
});

test('invoiceTotals.total equals subtotal (before VAT)', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 8500 },
      { qty: 3, unitPrice: 9500 },
    ],
  };
  const result = invoiceTotals(invoice);
  assert.equal(result.total, result.subtotal);
});

test('invoiceTotals works with a single line', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 6000 }],
  };
  const result = invoiceTotals(invoice);
  assert.equal(result.subtotal, 30000);
  assert.equal(result.total, 30000);
});

test('invoiceTotals works with mixed VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 8500, vatRate: 21 },
      { qty: 1, unitPrice: 2490, vatRate: 9 },
      { qty: 3, unitPrice: 60000, vatRate: 0 },
    ],
  };
  const result = invoiceTotals(invoice);
  assert.equal(result.subtotal, 2 * 8500 + 1 * 2490 + 3 * 60000);
  assert.equal(result.subtotal, 17000 + 2490 + 180000);
  assert.equal(result.subtotal, 199490);
});

test('invoiceTotals does not mutate the input', () => {
  const invoice = {
    lines: [{ qty: 2, unitPrice: 8500 }],
  };
  const invoiceCopy = JSON.stringify(invoice);
  invoiceTotals(invoice);
  assert.equal(JSON.stringify(invoice), invoiceCopy);
});

